using Godot;
using System;
using System.Linq;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class EnvironmentWorkspaceOperations
{
    private readonly TerrainBiomeOperations _biomes=new();
    private static readonly string[] BiomeNames={"Grassland","Forest","Desert","Tropical","Jungle","Savanna","Swamp","Snow / tundra","Alpine","Rocky mountains","Badlands","Volcanic","Coastal beach","Rocky coast"};
    internal void EditBiomes(Control owner,string id,Action<Resource> edit)
    {var terrain=_documents.terrain(Document(Session(owner)),id);if(terrain==null)return;var next=terrain.Get("biomes").As<Resource>()?.Duplicate(true)??GD.Load<GDScript>("res://Workspaces/EnvironmentWorkspace/terrain/terrain_biomes.gd").New().As<Resource>();edit(next);regenerate_terrain(owner,id,new Settings {["biomes"]=next},false,false);}
    public void edit_biomes(Control owner,string id,Settings edit)=>EditBiomes(owner,id,next=>owner.Call("_invoke_source_edit",edit,next));
    public void biome_properties(Control owner,Resource item,Resource terrain)
    {
        string terrainId=item.Get("id").AsString();var parent=Field<VBoxContainer>(owner,"properties");var canvas=Field<Control>(owner,"canvas");Heading(parent,"Climate & biomes");var source=terrain.Get("biomes").As<Resource>();if(source==null){Button(parent,"Add biome rules",()=>EditBiomes(owner,terrainId,next=>{var definitions=next.Get("definitions").AsGodotArray();definitions.Clear();foreach(int index in new[]{0,1,2,7})definitions.Add(_biomes.starter(index));}));return;}
        foreach(var spec in new[]{("Sea-level temperature (°C)","sea_temperature",-100.0,100.0,.5),("Base humidity","base_humidity",0.0,1.0,.01),("Altitude lapse (°C / m)","altitude_lapse",0.0,.1,.0005),("Climate region size","climate_region_size",1.0,100000.0,1.0)})Number(parent,spec.Item1,source.Get(spec.Item2).AsDouble(),spec.Item3,spec.Item4,spec.Item5,value=>EditBiomes(owner,terrainId,next=>next.Set(spec.Item2,value)));
        Menu(parent,"+ Biome",BiomeNames.Concat(new[]{"Custom"}).ToArray(),index=>EditBiomes(owner,terrainId,next=>{var definition=_biomes.starter(index<BiomeNames.Length?(int)index:0);definition["id"]=Guid.NewGuid().ToString("N");if(index==BiomeNames.Length)definition["name"]="Custom biome";next.Get("definitions").AsGodotArray().Add(definition);}));
        Menu(parent,"+ Cave biome",new[]{"Dry cave","Damp cave","Flooded cave","Cold cave","Limestone cave","Volcanic cave"},index=>EditBiomes(owner,terrainId,next=>{var definitions=next.Get("definitions").AsGodotArray();if(!_biomes.has_cave_rules(next)&&index!=0)definitions.Add(_biomes.cave_starter(0));var definition=_biomes.cave_starter((int)index);foreach(var value in definitions)if(value.AsGodotDictionary()["id"].AsString()==definition["id"].AsString()){definition["id"]=Guid.NewGuid().ToString("N");break;}definitions.Add(definition);}));
        var definitions=source.Get("definitions").AsGodotArray();for(int index=0;index<definitions.Count;index++)
        {
            int slot=index;var definition=definitions[index].AsGodotDictionary();string id=definition["id"].AsString();bool cave=Get(definition,"domain","surface").AsString()=="cave";Settings Definition(Resource next)=>next.Get("definitions").AsGodotArray()[slot].AsGodotDictionary();var row=new HBoxContainer();parent.AddChild(row);var toggle=new CheckBox {ButtonPressed=Get(definition,"enabled",true).AsBool()};row.AddChild(toggle);toggle.Toggled+=value=>EditBiomes(owner,terrainId,next=>Definition(next)["enabled"]=value);var expand=new Button {Text=Get(definition,"name","Biome").AsString(),ToggleMode=true,ButtonPressed=Get(State(owner,"_expanded_landforms"),id,false).AsBool()};row.AddChild(expand);expand.Toggled+=value=>{State(owner,"_expanded_landforms")[id]=value;owner.Set("_refresh_pending",true);};Button(row,"×",()=>EditBiomes(owner,terrainId,next=>next.Get("definitions").AsGodotArray().RemoveAt(slot)));if(!expand.ButtonPressed)continue;
            var name=new LineEdit {Text=definition["name"].AsString()};parent.AddChild(name);name.TextSubmitted+=value=>EditBiomes(owner,terrainId,next=>Definition(next)["name"]=value);foreach(var spec in new[]{("Frequency","frequency",0.0,1.0,.01),("Region size","region_size",1.0,100000.0,1.0),("Transition","transition",.001,1.0,.01),("Suitability weight","weight",0.0,100.0,.1)})Number(parent,spec.Item1,Get(definition,spec.Item2,1.0).AsDouble(),spec.Item3,spec.Item4,spec.Item5,value=>EditBiomes(owner,terrainId,next=>Definition(next)[spec.Item2]=value));
            string[] ranges={"temperature","humidity","altitude","slope","shore_distance","roughness"};if(cave)ranges=ranges.Concat(new[]{"cave_depth","submersion"}).ToArray();foreach(string key in ranges)for(int axis=0;axis<2;axis++){int component=axis;Number(parent,key.Capitalize()+(axis==0?" min":" max"),Get(definition,key,new Vector2(-100000,100000)).AsVector2()[axis],-100000,100000,.1,value=>EditBiomes(owner,terrainId,next=>{var target=Definition(next);var limits=Get(target,key,new Vector2(-100000,100000)).AsVector2();limits[component]=(float)value;target[key]=limits;}));}
            Button(parent,"Use as fallback",()=>EditBiomes(owner,terrainId,next=>next.Set(cave?"cave_fallback_id":"fallback_id",id)));if(!cave)Button(parent,"Paint biome mask",()=>{canvas.Get("biome_tool").As<RefCounted>().Set("biome_id",id);canvas.Set("environment_tool","Paint biome");refresh_context(owner);canvas.GrabFocus();});else{string[] faces={"any","floor","wall","ceiling"};var face=MenuChoice(parent,faces.Select(value=>value.Capitalize()).ToArray(),Math.Max(0,Array.IndexOf(faces,Get(definition,"surface_type","any").AsString())),which=>EditBiomes(owner,terrainId,next=>Definition(next)["surface_type"]=faces[which]));face.FitToLongestItem=false;for(int which=0;which<faces.Length;which++)face.SetItemMetadata(which,faces[which]);}
            Button(parent,"Add surface material…",()=>{var job=new EnvironmentWorkspaceFileJob();owner.AddChild(job);job.start(owner,"biome",terrainId,slot);});var materials=Get(definition,"materials",new GArray()).AsGodotArray();for(int material=0;material<materials.Count;material++){int targetSlot=material;var value=materials[material];string path=value.VariantType==Variant.Type.Dictionary?Get(value.AsGodotDictionary(),"source","").AsString():value.VariantType==Variant.Type.String?value.AsString():"";var materialRow=new HBoxContainer();parent.AddChild(materialRow);materialRow.AddChild(new Label {Text=value.VariantType is Variant.Type.String or Variant.Type.Dictionary?path.GetFile():"Surface material",TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});Button(materialRow,"×",()=>EditBiomes(owner,terrainId,next=>Definition(next)["materials"].AsGodotArray().RemoveAt(targetSlot)));}
            Menu(parent,"+ Biome landform",Landforms,selected=>EditBiomes(owner,terrainId,next=>{var target=Definition(next);var layers=Get(target,"landforms",new GArray()).AsGodotArray();layers.Add(new Settings {["type"]=Landforms[selected],["height"]=2.0,["width"]=5.0,["length"]=terrain.Get("dimensions").AsVector2().Y*.5,["center"]=Vector2.Zero});target["landforms"]=layers;}));
            var landforms=Get(definition,"landforms",new GArray()).AsGodotArray();for(int layer=0;layer<landforms.Count;layer++){int targetLayer=layer;var settings=landforms[layer].AsGodotDictionary();Heading(parent,Get(settings,"type","Landform").AsString());foreach(var spec in new[]{("Height","height",-10000.0,10000.0,.1),("Width","width",.1,100000.0,.1),("Length","length",.1,100000.0,.1),("Direction","direction",-360.0,360.0,1.0)})Number(parent,spec.Item1,Get(settings,spec.Item2,0.0).AsDouble(),spec.Item3,spec.Item4,spec.Item5,value=>EditBiomes(owner,terrainId,next=>Definition(next)["landforms"].AsGodotArray()[targetLayer].AsGodotDictionary()[spec.Item2]=value));Button(parent,"Remove landform",()=>EditBiomes(owner,terrainId,next=>Definition(next)["landforms"].AsGodotArray().RemoveAt(targetLayer)));}
        }
        Button(parent,"Remove climate & biomes",()=>regenerate_terrain(owner,terrainId,new Settings {["biomes"]=default},false,false));
    }
}
